@router.post("/checkout/coupons/apply")
@limiter.limit("5/minute")
def apply_cart_coupon(
    request: Request,
    payload: CouponApplyPayload,
    user: User = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    cart = db.query(Cart).filter(Cart.id == payload.cart_id, Cart.user_id == user.id).first()
    if not cart:
        raise HTTPException(status_code=404, detail="Cart not found")

    coupon = db.query(Coupon).filter(Coupon.code == payload.coupon_code, Coupon.is_active == True).first()
    if not coupon:
        raise HTTPException(status_code=400, detail="Invalid coupon code")

    cart.applied_coupon = coupon.code
    db.commit()
    return {"status": "coupon_applied", "cart_id": cart.id}
